css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .figura-mini{width: 38px; height: 38px;}
.mz .tabla-fig{width: 100%; border-collapse: collapse;}
.mz .tabla-fig th{border: 1.5px solid var(--bosque); background: #eee; font-size: 12px; padding: 4px 6px;}
.mz .tabla-fig td{border: 1.5px solid var(--bosque); text-align: center; padding: 4px 6px; height: 60px;}
.mz .celda-nombre{width: 38%;}
.mz .celda-num{width: 16%;}
.mz .linea-escribir{display: block; border-bottom: 1.5px solid var(--bosque); height: 22px; margin: 8px 10px 0;}
.mz .banco{border: 1.5px dashed #000; border-radius: 8px; padding: 5px 10px; text-align: center; font-size: 13px; font-weight: 700; margin-bottom: 6px;}
.mz .clasif-grid{display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px;}
.mz .clasif-caja{border: 1.5px solid var(--bosque); border-radius: 8px; overflow: hidden;}
.mz .clasif-titulo{background: #eee; border-bottom: 1.5px solid var(--bosque); font-size: 12px; font-weight: 700; text-align: center; padding: 3px 2px;}
.mz .clasif-hueco{min-height: 72px; padding: 4px 6px; display: flex; flex-direction: column; justify-content: space-evenly;}
.mz .clasif-linea{border-bottom: 1px solid #999; height: 24px;}
.mz .dibujar-grid{display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px;}
.mz .dibujar-caja{display: flex; flex-direction: column; align-items: center; gap: 4px;}
.mz .dibujar-titulo{font-size: 12.5px; font-weight: 700; text-align: center;}
.mz .dibujar-zona{border: 1.5px solid var(--bosque); border-radius: 8px; width: 100%; height: 130px;}
.mz .frases{display: flex; flex-direction: column; gap: 11px;}
.mz .frase{font-size: 13.5px; line-height: 1.5;}
.mz .hueco-frase{display: inline-block; border-bottom: 1.5px solid var(--bosque); min-width: 110px; height: 16px; vertical-align: bottom;}
.mz .hueco-num{display: inline-block; border: 1.5px solid var(--bosque); border-radius: 5px; width: 34px; height: 22px; vertical-align: middle;}
.mz .frase{line-height: 1.725 !important;}
